            M.tp(st.pos + Vector3.new(0, 3, 0))
            task.wait(0.35)
            for _ = 1, 4 do
                pcall(function() D.ParkReq:FireServer("EmptyTrashcan", t, st.bin.Name) end)
                task.wait(0.3)
                if (st.bin:GetAttribute("Count") or 0) == 0 then break end
            end
            if (st.bin:GetAttribute("Count") or 0) == 0 then S.cleans += 1 else F.trashSkip[st.bin] = os.clock() + 30 end
        end
    end)
    if M.alive() then M.tp(back) end
    M.busy = false
    return true
end
function M.invoke(fn)
    local out, done = nil, false
    local co = coroutine.create(function() local ok, r = pcall(fn) out = ok and r or nil done = true end)
    coroutine.resume(co)
    local t0 = os.clock()
    while not done and os.clock() - t0 < 6 do task.wait(0.1) end
    return out
end
F.menuSkip = setmetatable({}, { __mode = "k" })
function F.stallMenu()
    if not (on("f_menu") and D.SI and D.PCfg) or F.saving then return false end
    local t = M.tycoon()
    local bs = t and t:FindFirstChild("ButtonState")
    local df = lp:FindFirstChild("DataFolder")
    if not (bs and df and t:FindFirstChild("Stalls")) then return false end
    local budget = M.money() - M.keep()
    local now = os.clock()
    local best
    for _, s in ipairs(t.Stalls:GetChildren()) do
        local c = s:FindFirstChild("StallConfig")
        local st = c and bs:FindFirstChild(tostring(c:GetAttribute("ButtonName")))
        if st and st:GetAttribute("Bought") and (F.menuSkip[c] or 0) < now then
            local rows = D.SI.ForRows(c:GetAttribute("Rows") or s.Name)
            local mx = D.SI.MaxLevel(rows)
            local ov = df:FindFirstChild(D.SI.DataName(s.Name))
            local sv = df:FindFirstChild(D.SI.SalesName(s.Name))
            local owned, sales = ov and ov.Value or 0, sv and sv.Value or 0
            for _, it in ipairs(rows) do
                if not it.Exclusive and it.Level > 0 and not D.SI.Owns(it, owned, false) and sales >= D.SI.SalesGoal(it, rows) then
                    local price = D.PCfg.StallItemPrice(c:GetAttribute("MoneyPerCustomer") or 1, it.Level, mx)
                    if price <= budget and (not best or price < best.price) then best = { c = c, st = st, it = it, price = price, ov = ov, owned = owned } end
                end
            end
        end
    end
    if not best then return false end
    S.task = __T["Stall menu"]
    local got = false
    M.visit(best.st:GetAttribute("PadPosition"), function()
        local r = M.invoke(function() return D.StallReq:InvokeServer("Buy", best.c, best.it.Name) end)
        task.wait(0.3)
        got = r == true or (best.ov ~= nil and best.ov.Value ~= best.owned)
        return got
    end)
    if got then S.items += 1 LOG("menu", best.it.Name) else F.menuSkip[best.c] = os.clock() + 60 end
    return true
end
F.disp = { at = 0, seen = setmetatable({}, { __mode = "k" }) }
function F.dispatch()
    if not on("f_dispatch") or os.clock() - F.disp.at < 4 then return false end
    F.disp.at = os.clock()
    local t = M.tycoon()
    local res = M.invoke(function() return D.Snap:InvokeServer() end)
    if type(res) ~= "table" then return false end
    local mine
    for _, e in pairs(res) do if type(e) == "table" and e.Tycoon == t then mine = e end end
    if not (mine and type(mine.Rides) == "table") then return false end
    local bs = t:FindFirstChild("ButtonState")
    for _, r in ipairs(mine.Rides) do
        local k = type(r.Definition) == "table" and r.Definition.Key
        local st = k and bs and bs:FindFirstChild(k.Parent.Name)
        if k and not r.HasWorker and r.State == "Loading" and (r.Seated or 0) > 0 and (st == nil or st:GetAttribute("Bought")) then
            local first = F.disp.seen[k] or os.clock()
            F.disp.seen[k] = first
            if r.Seated >= (r.Required or 1) or os.clock() - first > 12 then
                S.task = __T["Starting "] .. tostring(k:GetAttribute("DisplayName") or k.Parent.Name)
                local ok = M.visit(k:GetAttribute("RepairStand"), function()
                    pcall(function() D.ParkReq:FireServer("Lever", k) end)
                    task.wait(0.5)
                    return true
                end)
                if ok then S.dispatches += 1 F.disp.seen[k] = nil LOG("dispatch", k.Parent.Name) end
                return true
            end
        elseif k then
            F.disp.seen[k] = nil
        end
    end
    return false
end
function F.parkLoop()
    while RUNNING do
        if M.alive() and not M.rebirthing() then
            pcall(F.repair)
            local busy = false
            if not M.busy then local ok, r = pcall(F.serve) busy = ok and r end
            if not busy and not M.busy then local ok, r = pcall(F.clean) busy = ok and r end
            if not busy and not M.busy then local ok, r = pcall(F.dispatch) busy = ok and r end
            if not busy and not M.busy then local ok, r = pcall(F.stallMenu) busy = ok and r end
            if not busy then pcall(F.capacity) end
        end
        task.wait(1)
    end
end
F.up = {}
F.upCats = {
    { "More Coins", "coinNode" }, { "Upgraders", "upgraderNode" }, { "VIP Guests", "vipNode" }, { "Auto Collect", "autoNode" },
    { "Engineers", "Engineer" }, { "Janitors", "Janitor" }, { "Staff Speed", "staffWorkNode" }, { "Gems", "diaNode" },
    { "XP", "xpNode" }, { "Starter Cash", "starterCashNode" }, { "Trash Cans", "TrashCapacity" }, { "Guest Limit", "oreLimitNode" },
    { "Speed + Jump", "speedNode" }, { "Other", "*" },
}
function F.upCatNames() local o = {} for _, c in ipairs(F.upCats) do o[#o + 1] = c[1] end return o end
F.infoCache = {}
function F.nodeInfo(id)
    local c = F.infoCache[id]
    if c then return c[1], c[2], c[3] end
    local base = id:gsub("%d+", "")
    local typ, num
    if D.Phone and type(D.Phone.getUpgradeTypeAndNumber) == "function" then typ, num = gcall(D.Phone.getUpgradeTypeAndNumber, id) end
    if not typ and D.Phone and D.Phone.mainPhonebook then for k, v in pairs(D.Phone.mainPhonebook) do if v == base then typ = k end end end
    if num == nil and id ~= "root" then num = tonumber((id:gsub("%D+", ""))) end
    F.infoCache[id] = { typ, num, base }
    return typ, num, base
end
function F.owned(id)
    local typ, num = F.nodeInfo(id)
    if not typ then return true end
    local v = M.data("upgrade_" .. typ)
    return (v or 0) >= (num or 1)
end
function F.catOf(base)
    for _, c in ipairs(F.upCats) do if c[2] == base then return c[1] end end
    if base == "jumpNode" then return "Speed + Jump" end
    if base == "EngineerSpeed" or base == "JanitorSpeed" then return "Staff Speed" end
    return "Other"
end
F.upTier = { root = 0, coinNode = 1, upgraderNode = 1, oreLimitNode = 1, vipNode = 1, autoNode = 1, dropperNode = 1, diaNode = 2, xpNode = 2, doubleXPNode = 2, Engineer = 2, staffWorkNode = 2, EngineerSpeed = 2, starterCashNode = 3, Janitor = 3, JanitorSpeed = 3 }
function F.upgrade()
    if not (on("f_up") and D.Nodes) then return end
    local robux = D.Phone and D.Phone.RobuxPricedNodes or {}
    local gems = M.data("Gems") or 0
    local ls = lp:FindFirstChild("leaderstats")
    local level = ls and ls:FindFirstChild("Level") and ls.Level.Value or 0
    local want = val("u_cats", {})
    local best, bp
    local now = os.clock()
    local reserve = math.huge
    for id, n in pairs(D.Nodes) do
        local price = type(n) == "table" and n.price
        if price and not robux[id] and tostring(price.currencyIcon):find("134039888088949") then
            local typ, _, base = F.nodeInfo(id)
            if typ and (F.upTier[base] or 4) <= 2 and not F.owned(id) and (n.parentNodeId == nil or F.owned(n.parentNodeId)) and want[F.catOf(base)] then
                reserve = math.min(reserve, tonumber(price.quantity) or math.huge)
            end
        end
    end
    if reserve == math.huge then reserve = 0 end
    for id, n in pairs(D.Nodes) do
        local price = type(n) == "table" and n.price
        if price and not robux[id] and (F.up[id] or 0) < now then
            local icon = tostring(price.currencyIcon)
            local q = tonumber(price.quantity) or 0
            local isGem, isLvl = icon:find("134039888088949") ~= nil, icon == "level"
            local typ, _, base = F.nodeInfo(id)
            if typ and (isGem or isLvl) and not F.owned(id) and (n.parentNodeId == nil or F.owned(n.parentNodeId)) and (want[F.catOf(base)] or id == "root") then
                local can = (isGem and q <= gems and ((F.upTier[base] or 4) <= 2 or gems - q >= reserve)) or (isLvl and q <= level)
                if can then
                    local cost = (F.upTier[base] or 4) * 1e9 + (isGem and q or 0)
                    if not bp or cost < bp then best, bp = id, cost end
                end
            end
        end
    end
    if not best then return end
    local typ, num = F.nodeInfo(best)
    local before = M.data("upgrade_" .. typ) or 0
    pcall(function() EV.UpgradesRelated.BuyUpgrade:FireServer(typ, num) end)
    task.wait(0.8)
    if (M.data("upgrade_" .. typ) or 0) > before then S.upgrades += 1 LOG("upgrade", best) else F.up[best] = os.clock() + 30 end
end
function F.slowLoop()
    while RUNNING do
        if M.alive() then
            pcall(F.advance)
            pcall(F.upgrade)
        end
        task.wait(1.2)
    end
end
