    end
    for _, c in ipairs(F.rides()) do
        if tostring(c:GetAttribute("DisplayName") or c.Parent.Name) == name then M.tp(c:GetAttribute("RepairStand") + Vector3.new(0, 3, 0)) return end
    end
end
